mapper.sql:
WHERE f.delete_yn = 'N'

  AND g.entity_type = #{search.entityType}


  AND g.site_id = #{search.siteId}


  AND f.virus_scan_status = #{search.virusScanStatus}


  AND f.original_name LIKE CONCAT('%', #{search.keyword}, '%')

mapper.select:
SELECT COUNT(1)
  FROM tb_file
 WHERE file_group_id = #{fileGroupId}
   AND file_hash     = #{fileHash}
   AND delete_yn     = 'N'

mapper.delete:
DELETE FROM tb_file
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
